class Solution
{
public:
    int threeSumSmaller(vector< int>& nums, int target)
    {
        sort(nums.begin(), nums.end());
        int ans = 0, n = nums.size();
        for (int i = 0; i < n;++i)
        {
            int l = i + 1, r = n - 1;
            while (l < r)
            {
                if ((long long) nums[i] + nums[l] + nums[r] < target)
                {
                    ans += r - l;
                    ++l;
                }
                else--r;
            }
        }
        return ans;
    }
};
